(* [comment removed for export] *)
Definition w4s33_ctx (RNG : footprint) (mm : amem) (P DT4 DBL DBH DST dcap tl SS n SBL SBH S3 : Z)
    (cells : list deltX1) : Prop :=
  w4s1_dctx RNG mm P DT4 DBL DBH DST dcap tl /\
  bytes_at asegs mm DT4 (firstn (Z.to_nat (2 * 2^tl)) (x1_bytes cells)) /\
  w4s_src_ctx RNG mm SS n SBL SBH /\
  rw_cells asegs mm (P + 192) [C8 (Z_to_bv 64 (S3 + 8))] /\
  rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] /\
  rw_cells asegs mm (P + 112) [C8 (Z_to_bv 64 S3)].

Lemma w4s33_ctx_tr2 : forall RNG mm mm' P DT4 DBL DBH DST dcap tl SS n SBL SBH S3 cells,
  w4s33_ctx RNG mm P DT4 DBL DBH DST dcap tl SS n SBL SBH S3 cells ->
  munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> x1_table_ok cells tl ->
  KXGoM.apart SS n P 496 -> KXGoM.apart DST dcap SS n -> 1 <= dcap -> 1 <= n ->
  w4s33_ctx RNG mm' P DT4 DBL DBH DST dcap tl SS n SBL SBH S3 cells.
