(* [comment removed for export] *)
Lemma w4s33_round : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x9 x10 x12 x13 x14 x15 x16 x18 x20 x25 x26 x27 x28 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl mtl PE SS n SBL SBH S3 L3 PTR BITS PP : Z) (cells : list deltX1) (obuf : list Z),
  w4s33_ctx RNG mm P DT4 DBL DBH DST dcap tl SS n SBL SBH S3 cells -> mem_inv asegs mm ->
  x1_table_ok cells tl -> u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
  n < 2^26 -> KXGoM.apart SS n P 496 -> KXGoM.apart DST dcap SS n ->
  SS <= S3 -> S3 + L3 <= SS + n -> 8 <= S3 -> S3 + 16 <= 2^47 ->
  S3 <= PTR -> (PTR = S3 \/ PTR + 8 <= S3 + L3) -> 0 <= BITS <= 64 ->
  DST <= PP -> PP <= PE -> DST + 4 <= PE -> PE <= DST + dcap -> DST + dcap < 2^47 -> 1 <= mtl <= 12 ->
  (forall (mm' : amem) (PTR' B' : Z) (y13 y14 y15 y26 y28 y29 y30 y31 : word),
     munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
     S3 <= PTR' -> (PTR' = S3 \/ PTR' + 8 <= S3 + L3) -> 0 <= B' <= 64 -> PP + 4 <= PE ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 (PP + 4))
          (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 (PP + 4)) x12 y13 y14 y15 x16 (Z_to_bv 64 64) x18 (Z_to_bv 64 B') x20
          (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT4) (Z_to_bv 64 PE) (Z_to_bv 64 PTR') x25 y26 x27 y28 y29 y30
          y31) F (Z_to_bv 64 0x92404) fc None mm' (seg_rom asegs))) ->
  (forall (mm' : amem) (B' : Z) (cw y13 y14 y15 y24 y28 y29 y30 y31 : word),
     munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) -> 0 <= B' <= 64 ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 PP)
          (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PP) x12 y13 y14 y15 x16 (Z_to_bv 64 64) x18 (Z_to_bv 64 B') x20 (Z_to_bv
          64 (tl + 256 * mtl)) (Z_to_bv 64 DT4) (Z_to_bv 64 PE) y24 x25 cw x27 y28 y29 y30 y31) F (Z_to_bv 64 0x92864)
          fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 PP)
      (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PP) x12 x13 x14 x15 x16 (Z_to_bv 64 64) x18 (Z_to_bv 64 BITS) x20 (Z_to_bv 64
      (tl + 256 * mtl)) (Z_to_bv 64 DT4) (Z_to_bv 64 PE) (Z_to_bv 64 PTR) x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64
      0x92404) fc None mm (seg_rom asegs)).
