Lemma w4s33_else : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x5 x6 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl SS n SBL SBH S3 L3 PTR BITS PP : Z) (cells : list deltX1),
  w4s33_ctx RNG mm P DT4 DBL DBH DST dcap tl SS n SBL SBH S3 cells -> mem_inv asegs mm -> n < 2^26 -> KXGoM.apart SS n P 496 ->
  SS <= S3 -> S3 + L3 <= SS + n -> 8 <= S3 -> S3 + 16 <= 2^47 ->
  S3 <= PTR -> (PTR = S3 \/ PTR + 8 <= S3 + L3) -> 0 <= BITS < 2^31 ->
  (forall (B' : Z) (cw y5 y6 y11 y13 y14 y15 y17 : word), 0 <= B' < 2^31 ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp y5 y6 (Z_to_bv 64 PP) (Z_to_bv 64 S3) x9 x10 y11 x12 y13 y14 y15 x16
          y17 x18 (Z_to_bv 64 B') x20 x21 x22 x23 (Z_to_bv 64 PTR) x25 cw x27 x28 x29 x30 x31) F (Z_to_bv 64 0x92864)
          fc None mm (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 (Z_to_bv 64 PP) (Z_to_bv 64 S3) x9 x10 x11 x12 x13 x14 x15 x16
      x17 x18 (Z_to_bv 64 BITS) x20 x21 x22 x23 (Z_to_bv 64 PTR) x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x926fc)
